   122	        for( ; br->crc16_align < FLAC__BITS_PER_WORD; br->crc16_align += 8)
   123	                crc = FLAC__CRC16_UPDATE((uint32_t)((word >> (FLAC__BITS_PER_WORD-8-br->crc16_align)) & 0xff), crc);
   124	
   125	        br->read_crc16 = crc;
   126	        br->crc16_align = 0;
   127	}
